    fixture.assert_scalar::<i64>("SELECT COUNT(*) FROM controls", 0);
    fixture.assert_scalar::<i64>(
        "SELECT COUNT(*) FROM recovery_records WHERE session_id='m4b-prior-session' AND state='attention_required'",1,
    );
